const items = $input.all();
if (items.length !== 1) throw new Error('Expected one funding response');
const evidence = items[0].json;
if (evidence.schema !== 'seiche.public.v2' || typeof evidence.generated_at !== 'string' || !Number.isFinite(Date.parse(evidence.generated_at)) || !evidence.data_quality || typeof evidence.data_quality !== 'object' || Array.isArray(evidence.data_quality)) throw new Error('Unexpected funding evidence contract');
return [{ json: { schema: 'liquilens.n8n-funding-research.v1', endpoint: 'https://api.seiche.info/api/public', retrieved_at: new Date().toISOString(), execution_authority: false, note: 'Retrieval time is not source freshness. Inspect data_quality, headline source ages and each cited observation date.', evidence } }];
